    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "`listed` is required. The profile replaces the whole stored profile, so a missing flag would have to be guessed — and guessing `true` publishes a vetter who never said so.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
            (
                "`methods` is required, even when unlisting. A partial payload is not a patch: the profile is replaced as a whole.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [],\n  \"listed\": false\n}",
            ),
            (
                "A vetter offers at least one method; an empty list could never match a request.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": []\n}",
            ),
            (
                "Methods come from the shared VettingMethod vocabulary, lowerCamelCase. `in-person` is not one.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"in-person\"\n  ]\n}",
            ),
            (
                "A method is listed once; `uniqueItems` refuses a repeat.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\",\n    \"video\"\n  ]\n}",
            ),
            (
                "`displayName` is 1–128 characters when present. An empty string is not an absent name — omit the member instead.",
                "{\n  \"acceptsDocumentation\": [],\n  \"displayName\": \"\",\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
            (
                "Language tags are BCP 47, not language names.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"English\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
            (
                "At most 16 languages.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"aa\",\n    \"ab\",\n    \"ae\",\n    \"af\",\n    \"ak\",\n    \"am\",\n    \"an\",\n    \"ar\",\n    \"as\",\n    \"av\",\n    \"ay\",\n    \"az\",\n    \"ba\",\n    \"be\",\n    \"bg\",\n    \"bh\",\n    \"bi\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
            (
                "`location.country` is an upper-case ISO 3166-1 alpha-2 code. `de` is lower case.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"de\"\n  ],\n  \"listed\": true,\n  \"location\": {\n    \"country\": \"de\"\n  },\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "`location` needs a country; a city on its own is ambiguous.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"de\"\n  ],\n  \"listed\": true,\n  \"location\": {\n    \"city\": \"Vienna\"\n  },\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "A location is coarse — country, region, city. There is no street address member, and a vetter's home is not something a listing should carry.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"de\"\n  ],\n  \"listed\": true,\n  \"location\": {\n    \"country\": \"AT\",\n    \"street\": \"Stephansplatz 1\"\n  },\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "Documentation classes use the shared lowerCamelCase token. `national-id` is not one.",
                "{\n  \"acceptsDocumentation\": [\n    \"national-id\"\n  ],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "`contactHint` is at most 300 characters.",
                "{\n  \"acceptsDocumentation\": [],\n  \"contactHint\": \"\",\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
            (
                "An event date is `YYYY-MM-DD`. A date-time is refused: events are listed by UTC date.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [\n    {\n      \"endDate\": \"2026-11-13\",\n      \"name\": \"Linux Plumbers Conference 2026\",\n      \"startDate\": \"2026-11-11T09:00:00Z\"\n    }\n  ],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "An event carries `endDate`; a single-day event repeats its `startDate`.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [\n    {\n      \"name\": \"Linux Plumbers Conference 2026\",\n      \"startDate\": \"2026-11-11\"\n    }\n  ],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "An event `url` is https. A plain-http link would let anyone on the applicant's network rewrite where they go.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [\n    {\n      \"endDate\": \"2026-11-13\",\n      \"name\": \"Linux Plumbers Conference 2026\",\n      \"startDate\": \"2026-11-11\",\n      \"url\": \"http://lpc.events/\"\n    }\n  ],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"inPerson\"\n  ]\n}",
            ),
            (
                "No `vetterDid` member. The vetter is the authenticated sender; a payload naming a DID would invite a profile for someone else.",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ],\n  \"vetterDid\": \"did:webvh:QmCarolScid1:kernel-vtc.example:carol\"\n}",
            ),
            (
                "`ext` keys must be reverse-DNS namespaces (SPEC §4.5.1).",
                "{\n  \"acceptsDocumentation\": [],\n  \"events\": [],\n  \"ext\": {\n    \"mine\": {}\n  },\n  \"languages\": [\n    \"en\"\n  ],\n  \"listed\": true,\n  \"methods\": [\n    \"video\"\n  ]\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
